-- Cabin Crew · Dinâmicas de grupo (biblioteca do Head Hunter), importadas da Horsky
--   • 100 dinâmicas em 10 categorias: objetivo, materiais, como é realizada e como se destacar
--   • pode rodar mais de uma vez: atualiza o que já existe, não duplica
--   • entram visíveis para os alunos; para esconder alguma: Admin › Head Hunter › Dinâmicas

begin;

insert into dinamicas_categorias (slug, titulo, descricao, ordem, ativo) values
  ('quebra-gelo', 'Quebra-Gelo e Apresentação', 'Dinâmicas para iniciar encontros e conhecer os participantes', 1, true),
  ('trabalho-em-equipe', 'Trabalho em Equipe', 'Atividades que desenvolvem colaboração e cooperação', 2, true),
  ('comunicacao', 'Criatividade e Comunicação', 'Dinâmicas para estimular a expressão e a criatividade', 3, true),
  ('resolucao-de-problemas', 'Análise de Problemas', 'Exercícios de resolução de problemas e pensamento crítico', 4, true),
  ('inovacao', 'Criatividade e Inovação', 'Dinâmicas para pensar fora da caixa', 5, true),
  ('autoconhecimento', 'Autoconhecimento', 'Atividades de reflexão pessoal e autoavaliação', 6, true),
  ('lideranca', 'Liderança Situacional', 'Exercícios que desenvolvem habilidades de liderança', 7, true),
  ('energizadores', 'Dinâmicas Energizantes', 'Atividades rápidas para energizar o grupo', 8, true),
  ('encerramento', 'Encerramento e Integração', 'Atividades para fechar o encontro com reconhecimento e conexão entre o grupo', 9, true),
  ('planejamento', 'Planejamento e Feedback', 'Atividades para organizar ações, dar e receber feedback', 10, true)
on conflict (slug) do update set titulo = excluded.titulo, descricao = excluded.descricao, ordem = excluded.ordem, ativo = true;

insert into dinamicas (origem_id, categoria_id, titulo, objetivo, materiais, como_realizada, como_se_destacar, ordem, ativo)
select v.origem, c.id, v.titulo, v.objetivo, v.materiais, v.como, v.destaque, v.ordem, v.ativo from (values
  ('ca83f4d6-33b8-4484-88de-473d4cdb4201', 'quebra-gelo', 'Apresentação Criativa', 'Conhecer os participantes de forma descontraída e memorável.', 'Nenhum material necessário.', 'Cada participante se apresenta dizendo seu nome e associando-o a algo que comece com a mesma letra (ex: ''Sou Maria e amo manga'').', 'Seja criativo e use associações relacionadas à aviação ou atendimento ao cliente. Ex: ''Sou Ana e adoro ajudar passageiros ansiosos''.', 1, true),
  ('79c3267b-98a7-4903-a1d9-8016d561f7b2', 'quebra-gelo', 'Duas Verdades e Uma Mentira', 'Promover interação e descobrir curiosidades sobre os colegas.', 'Nenhum material necessário.', 'Cada pessoa conta três fatos sobre si, sendo um falso. Os outros tentam adivinhar qual é a mentira.', 'Escolha fatos que demonstrem experiências relevantes para a função, como viagens internacionais ou situações de atendimento ao público.', 2, true),
  ('1e2bd529-ffe2-44fd-aa0f-b085836d6635', 'quebra-gelo', 'Entrevista Relâmpago', 'Conhecer rapidamente os participantes através de perguntas rápidas.', 'Lista de perguntas preparadas.', 'Em duplas, os participantes têm 2 minutos para fazer perguntas rápidas um ao outro, depois apresentam o colega ao grupo.', 'Faça perguntas inteligentes e memorize bem as respostas. Apresente seu par com entusiasmo e destaque qualidades relevantes.', 3, true),
  ('bca8ec63-6625-4d10-80dd-6b90b48327e3', 'quebra-gelo', 'Bingo Humano', 'Estimular a circulação e descoberta de características comuns.', 'Cartelas de bingo com características variadas.', 'Cada participante recebe uma cartela com características. Deve encontrar pessoas que correspondam a cada item e coletar assinaturas.', 'Seja proativo, circule por todo o grupo e demonstre genuíno interesse nas histórias das pessoas.', 4, true),
  ('a5a04254-9536-4737-a609-6be9e237537c', 'quebra-gelo', 'O Objeto Que Me Representa', 'Permitir que os participantes compartilhem algo pessoal de forma simbólica.', 'Cada participante traz um objeto pessoal.', 'Cada pessoa apresenta um objeto que trouxe e explica por que ele a representa.', 'Escolha um objeto que demonstre valores alinhados à aviação: segurança, cuidado, aventura ou profissionalismo.', 5, true),
  ('7c3ee35e-3827-4144-92d9-2867d6461272', 'quebra-gelo', 'Linha do Tempo Coletiva', 'Criar conexão através de experiências compartilhadas em diferentes épocas.', 'Papel grande, canetas coloridas, fita adesiva.', 'Uma linha do tempo é desenhada. Participantes marcam eventos importantes de suas vidas, buscando conexões com outros.', 'Inclua marcos profissionais e experiências que demonstrem seu interesse pela carreira de comissário(a).', 6, true),
  ('d61048e3-faa1-4971-a339-94137e6e8195', 'quebra-gelo', 'Speed Dating Profissional', 'Conhecer muitas pessoas em pouco tempo através de conversas breves.', 'Cronômetro, cadeiras organizadas em duas fileiras.', 'Participantes sentam em duas fileiras frente a frente. A cada 2 minutos, trocam de par após breve conversa.', 'Prepare um pitch pessoal conciso. Demonstre escuta ativa e faça perguntas relevantes em cada interação.', 7, true),
  ('3d03840d-cbe7-4163-8800-6f41c53a7f56', 'quebra-gelo', 'Mapa de Viagens', 'Compartilhar experiências de viagem e criar conexões através de lugares visitados.', 'Mapa grande, post-its coloridos, canetas.', 'Participantes marcam no mapa lugares que visitaram e compartilham uma história sobre cada local.', 'Conte histórias que demonstrem adaptabilidade cultural, curiosidade e respeito por diferentes culturas.', 8, true),
  ('51130837-74d5-47d4-a117-fda02f22ac73', 'quebra-gelo', 'Foto da Infância', 'Criar intimidade através de memórias de infância.', 'Cada participante traz uma foto de infância.', 'As fotos são colocadas em um painel. O grupo tenta adivinhar quem é quem, depois cada um conta uma história sobre sua foto.', 'Conte uma história que revele valores positivos formados desde cedo, como responsabilidade ou espírito de ajuda.', 9, true),
  ('dd2f07ae-4042-49fc-9abf-aa4f2485ac01', 'quebra-gelo', 'Círculo de Semelhanças', 'Descobrir pontos em comum entre os participantes.', 'Espaço amplo para movimentação.', 'Um facilitador faz afirmações. Quem se identificar, vai ao centro do círculo. Isso revela semelhanças entre os participantes.', 'Participe ativamente e use os momentos no centro para fazer contato visual e sorrir para os colegas.', 10, true),
  ('0bbae0f7-10a6-43a5-ac78-61f657450741', 'trabalho-em-equipe', 'Torre de Papel', 'Desenvolver trabalho em equipe e planejamento estratégico.', 'Folhas de papel, fita adesiva, tesoura.', 'Equipes têm tempo limitado para construir a torre mais alta usando apenas os materiais fornecidos.', 'Assuma papel de facilitador, organize ideias do grupo e mantenha todos engajados. Não domine, colabore.', 1, true),
  ('1f004de3-c014-48e2-84ba-38859137e7a6', 'trabalho-em-equipe', 'Nó Humano', 'Trabalhar comunicação e resolução de problemas em grupo.', 'Nenhum material necessário.', 'Participantes em círculo dão as mãos aleatoriamente, formando um nó. Devem se desenrolar sem soltar as mãos.', 'Mantenha a calma, sugira movimentos e encoraje colegas que pareçam frustrados. Demonstre paciência.', 2, true),
  ('ee9a4977-564a-45cc-af7d-a05f3a57af89', 'trabalho-em-equipe', 'Construção às Cegas', 'Desenvolver comunicação clara e confiança.', 'Vendas, blocos de montar ou objetos empilháveis.', 'Um participante vendado deve construir algo seguindo apenas instruções verbais de um colega.', 'Se for o guia, dê instruções claras e pacientes. Se for o construtor, demonstre confiança e peça esclarecimentos.', 3, true),
  ('0f1fb5f2-c2a0-48a5-be4e-55d14575a1a0', 'trabalho-em-equipe', 'Passagem do Bambolê', 'Trabalhar coordenação e comunicação não-verbal.', 'Bambolê ou arco.', 'Em círculo de mãos dadas, o grupo deve passar o bambolê por todos sem soltar as mãos.', 'Ajude colegas com dificuldade, celebre pequenas vitórias e mantenha energia positiva.', 4, true),
  ('f75b5c1a-5ec5-4e64-b5b7-f220f6d2c3df', 'trabalho-em-equipe', 'Desafio da Ponte', 'Desenvolver planejamento colaborativo e execução em equipe.', 'Palitos de picolé, barbante, cola, peso para teste.', 'Equipes devem construir uma ponte que suporte um peso específico usando apenas os materiais dados.', 'Proponha soluções, mas esteja aberto a ideias dos outros. Teste antes de finalizar e aprenda com erros.', 5, true),
  ('a2b2cfb1-f778-40eb-b9d7-10b43f239664', 'trabalho-em-equipe', 'Jogo da Sobrevivência', 'Praticar tomada de decisão em grupo e argumentação.', 'Lista de itens de sobrevivência, papel e caneta.', 'Após um cenário de acidente, o grupo deve ranquear itens de sobrevivência por importância, chegando a consenso.', 'Apresente argumentos lógicos, ouça perspectivas diferentes e ajude o grupo a chegar a acordo sem imposição.', 6, true),
  ('f16b4148-2f30-4b90-8335-b0800e298898', 'trabalho-em-equipe', 'Campo Minado', 'Desenvolver confiança e comunicação precisa.', 'Vendas, obstáculos variados para criar o campo.', 'Um participante vendado deve atravessar um campo de obstáculos guiado apenas pela voz de um colega.', 'Seja um guia calmo e preciso. Como vendado, demonstre confiança no parceiro e agradeça a ajuda.', 7, true),
  ('d0d046af-6f01-467d-ba62-a1302640da83', 'trabalho-em-equipe', 'Corrente de Criatividade', 'Construir ideias coletivamente através de contribuições sequenciais.', 'Papel grande, canetas coloridas.', 'Uma pessoa começa um desenho ou história. A cada 30 segundos, o próximo continua de onde o anterior parou.', 'Conecte sua contribuição de forma criativa ao que veio antes, demonstrando atenção e adaptabilidade.', 8, true),
  ('9db5a2c4-de30-4863-ac11-f904a382fa08', 'trabalho-em-equipe', 'Quebra-Cabeça em Equipe', 'Trabalhar divisão de tarefas e comunicação.', 'Quebra-cabeça dividido em partes para cada subgrupo.', 'Cada subgrupo monta sua parte. Depois, todos se unem para completar o quebra-cabeça inteiro.', 'Organize seu subgrupo eficientemente e facilite a integração com outros grupos na fase final.', 9, true),
  ('47367c27-6747-4f17-bce4-9d61bbe0a156', 'trabalho-em-equipe', 'Corrida de Revezamento Criativa', 'Combinar velocidade com colaboração e criatividade.', 'Materiais variados para cada estação de desafio.', 'Equipes passam por estações com desafios diferentes. Cada membro completa uma etapa antes de passar ao próximo.', 'Encoraje seus colegas, celebre cada etapa completada e mantenha energia positiva mesmo sob pressão.', 10, true),
  ('0b7c7673-7352-4092-a5f8-948e5a1202d9', 'comunicacao', 'Storytelling Coletivo', 'Desenvolver criatividade narrativa e escuta ativa.', 'Objeto para passar (bola, bastão).', 'Uma pessoa começa uma história. Ao receber o objeto, o próximo deve continuar de onde o anterior parou.', 'Mantenha coerência com a história, adicione elementos surpreendentes e crie conexões lógicas.', 1, true),
  ('9953efc3-32fe-4e9d-b9ef-2c55afb4ae2c', 'comunicacao', 'Mímica Profissional', 'Praticar comunicação não-verbal e criatividade.', 'Cartões com situações profissionais.', 'Participantes representam situações de trabalho apenas com gestos enquanto outros adivinham.', 'Use expressões faciais claras, gestos amplos e demonstre situações relevantes para aviação com criatividade.', 2, true),
  ('8ea55ee2-30b2-427d-a603-8941958194d9', 'comunicacao', 'Debate Criativo', 'Desenvolver argumentação e pensamento rápido.', 'Temas controversos escritos em cartões.', 'Duplas recebem um tema e lados opostos para defender. Devem argumentar mesmo que não concordem pessoalmente.', 'Argumente com respeito, use exemplos concretos e demonstre capacidade de ver múltiplas perspectivas.', 3, true),
  ('104a0e40-50b6-4b18-86c2-9382e906bbe0', 'comunicacao', 'Pitch de 60 Segundos', 'Praticar síntese e comunicação persuasiva.', 'Cronômetro, temas ou produtos fictícios.', 'Cada participante tem 60 segundos para apresentar uma ideia ou ''vender'' um produto de forma convincente.', 'Estruture bem seu tempo: problema, solução, benefício. Use entusiasmo e contato visual.', 4, true),
  ('5d657850-39e6-4b60-9423-9a0af07449b5', 'comunicacao', 'Telefone sem Fio Visual', 'Trabalhar interpretação e comunicação criativa.', 'Papel, canetas.', 'Uma pessoa desenha algo. A próxima descreve sem mostrar. A terceira desenha baseada na descrição. Comparar início e fim.', 'Seja detalhista nas descrições e criativo nos desenhos. Ria das distorções sem culpar ninguém.', 5, true),
  ('ad51f001-6b8d-4e4c-9f0c-d069e479b384', 'comunicacao', 'Improvisação Teatral', 'Desenvolver pensamento rápido e expressividade.', 'Cartões com situações para improvisar.', 'Duplas ou pequenos grupos recebem uma situação e devem improvisar uma cena sem preparação.', 'Aceite as propostas dos colegas (regra do ''sim, e...''), seja expressivo e mantenha a cena fluindo.', 6, true),
  ('273541af-e6ed-46db-ab17-95b4b9214352', 'comunicacao', 'Brainstorm Estruturado', 'Gerar ideias criativas de forma organizada.', 'Post-its, quadro ou parede, canetas.', 'Grupo recebe um desafio. Primeiro, ideias individuais em post-its. Depois, agrupam e desenvolvem as melhores juntos.', 'Contribua com muitas ideias, por mais malucas que pareçam. Valorize e desenvolva ideias dos outros.', 7, true),
  ('b47435eb-6f12-41f7-b40f-3447bf7f810c', 'comunicacao', 'Apresentação com Objeto', 'Desenvolver criatividade e capacidade de improvisação.', 'Objetos variados (utensílios, brinquedos, etc.).', 'Cada participante recebe um objeto aleatório e deve fazer uma apresentação criativa sobre ele como se fosse revolucionário.', 'Seja entusiasmado, encontre ''benefícios'' inusitados e divirta a plateia enquanto mantém profissionalismo.', 8, true),
  ('65dace56-3af1-4120-80d9-570232502ea1', 'comunicacao', 'Notícia do Futuro', 'Estimular visão de futuro e criatividade narrativa.', 'Papel, canetas, materiais para apresentação visual.', 'Grupos criam uma manchete de jornal do futuro sobre uma conquista imaginária e apresentam a ''notícia'' completa.', 'Conecte a notícia com tendências reais, seja criativo mas plausível, e apresente com entusiasmo jornalístico.', 9, true),
  ('d533403d-33ab-4129-8277-47b2ed5d7802', 'comunicacao', 'Comunicação de Crise', 'Praticar comunicação clara sob pressão.', 'Cenários de crise escritos em cartões.', 'Participantes recebem um cenário de crise e devem comunicar a situação para diferentes públicos (equipe, clientes, imprensa).', 'Mantenha calma, seja claro e empático. Adapte a mensagem para cada público demonstrando inteligência emocional.', 10, true),
  ('a8bde7f2-cd81-4189-ba0d-932bc0786310', 'resolucao-de-problemas', 'Estudo de Caso Real', 'Aplicar conhecimentos em situações práticas do mercado.', 'Descrição detalhada de um caso empresarial.', 'Grupos analisam um caso real, identificam problemas e propõem soluções, depois apresentam suas conclusões.', 'Faça análise estruturada: contexto, problema, causas, alternativas, recomendação. Seja específico nas soluções.', 1, true),
  ('b4371988-af90-41c8-9e3e-b69cc5ae64d2', 'resolucao-de-problemas', 'Os 5 Porquês', 'Desenvolver análise profunda de causas raiz.', 'Problemas escritos em cartões, papel e caneta.', 'Diante de um problema, o grupo pergunta ''por quê?'' cinco vezes consecutivas para chegar à causa raiz.', 'Questione de forma construtiva, evite respostas superficiais e conecte as causas de forma lógica.', 2, true),
  ('db34b777-f8b8-413c-b775-85214c77554f', 'resolucao-de-problemas', 'SWOT Pessoal', 'Desenvolver autoconhecimento estratégico.', 'Folhas com matriz SWOT, canetas.', 'Cada participante preenche uma matriz SWOT sobre si mesmo, depois compartilha insights com o grupo.', 'Seja honesto nas fraquezas, específico nas forças e conecte oportunidades com a carreira de comissário(a).', 3, true),
  ('5f83017e-b9a8-46a6-98fe-2cafe1ec327a', 'resolucao-de-problemas', 'Análise de Stakeholders', 'Entender diferentes perspectivas em uma situação.', 'Cenário complexo com múltiplos envolvidos.', 'Cada participante assume o papel de um stakeholder diferente e apresenta sua perspectiva sobre o mesmo problema.', 'Mergulhe no papel, defenda os interesses do seu stakeholder e busque soluções que atendam múltiplas partes.', 4, true),
  ('8a9ca69c-cc36-4321-9b7e-7cfdd54a2e5a', 'resolucao-de-problemas', 'Reversão de Problema', 'Estimular pensamento criativo através de inversão.', 'Problema definido, papel e caneta.', 'Em vez de como resolver, o grupo pensa em como piorar o problema. Depois, inverte as ideias para encontrar soluções.', 'Seja criativo ao piorar o problema e perspicaz ao inverter. Demonstre pensamento lateral.', 5, true),
  ('ff400744-1c4b-4308-8923-9ecbbb1037ce', 'resolucao-de-problemas', 'Mapa Mental Coletivo', 'Organizar informações de forma visual e colaborativa.', 'Papel grande, canetas coloridas, post-its.', 'A partir de um tema central, o grupo cria ramificações de ideias conectadas, construindo um mapa mental coletivo.', 'Sugira conexões entre ideias de diferentes pessoas e ajude a organizar visualmente de forma clara.', 6, true),
  ('14ef19c1-d05e-41a1-9142-d68368867d0e', 'resolucao-de-problemas', 'Tribunal de Ideias', 'Praticar defesa e questionamento de propostas.', 'Propostas ou ideias escritas, espaço para apresentação.', 'Uma ideia é apresentada. Alguns defendem, outros questionam. O grupo decide se a ideia é aprovada ou não.', 'Se defender, use argumentos sólidos. Se questionar, seja respeitoso mas incisivo. Aceite o veredicto com maturidade.', 7, true),
  ('130636ce-f12c-4f8c-b32c-77bbf0d16a80', 'resolucao-de-problemas', 'Priorização por Matriz', 'Tomar decisões baseadas em critérios objetivos.', 'Matriz de priorização impressa, itens para priorizar.', 'O grupo usa uma matriz (urgência x importância, por exemplo) para priorizar tarefas ou soluções.', 'Argumente com base nos critérios, não em preferências pessoais. Ajude o grupo a ser objetivo.', 8, true),
  ('398c5ebe-4d97-4c57-8aac-0c68593e0adb', 'resolucao-de-problemas', 'Cenários Futuros', 'Desenvolver pensamento estratégico e visão de longo prazo.', 'Descrição de situação atual, papel e caneta.', 'Grupos criam três cenários futuros (otimista, pessimista, realista) e definem ações para cada um.', 'Baseie cenários em tendências reais e proponha ações práticas. Demonstre visão estratégica.', 9, true),
  ('4a81698d-9fda-42ad-a631-420288d8d1e2', 'resolucao-de-problemas', 'Análise de Riscos', 'Identificar e mitigar riscos em projetos ou decisões.', 'Projeto ou decisão para análise, matriz de riscos.', 'Grupos identificam riscos potenciais, avaliam probabilidade e impacto, e propõem medidas de mitigação.', 'Identifique riscos que outros não perceberam e proponha soluções práticas de mitigação.', 10, true),
  ('584b04fc-eb6b-471c-8dd5-ddbef75f3a58', 'inovacao', 'SCAMPER', 'Gerar inovações através de modificações sistemáticas.', 'Produto ou serviço para análise, checklist SCAMPER.', 'Usando as técnicas SCAMPER (Substituir, Combinar, Adaptar, Modificar, Por outros usos, Eliminar, Reverter), o grupo propõe inovações.', 'Aplique cada técnica de forma criativa e proponha combinações inovadoras entre diferentes modificações.', 1, true),
  ('b692af3a-32e2-4d4d-a0c2-fbca30347792', 'inovacao', 'Crazy 8s', 'Gerar muitas ideias rapidamente sem autocensura.', 'Papel A4 dobrado em 8 partes, canetas, cronômetro.', 'Cada pessoa tem 8 minutos para desenhar 8 ideias diferentes (1 por quadrante). Depois, compartilham e votam nas melhores.', 'Não se preocupe com qualidade do desenho. Foque em quantidade e variedade. Explique suas ideias com entusiasmo.', 2, true),
  ('14cee2d6-1ad8-46af-95f6-b92707cd73f2', 'inovacao', 'Design Thinking Sprint', 'Aplicar metodologia de inovação em desafio real.', 'Materiais para prototipagem, post-its, canetas.', 'Grupos passam por fases: empatia, definição, ideação, prototipagem e teste, desenvolvendo soluções inovadoras.', 'Engaje em cada fase, contribua com insights de usuário e seja hands-on na prototipagem.', 3, true),
  ('d2dd1c7d-75de-4ce9-95f8-dd1ddc49624e', 'inovacao', 'Analogias Forçadas', 'Encontrar soluções através de conexões inusitadas.', 'Cartões com objetos ou conceitos aleatórios.', 'O grupo recebe um problema e um objeto/conceito aleatório. Deve encontrar analogias que gerem soluções.', 'Faça conexões inesperadas e desenvolva as analogias até encontrar aplicações práticas.', 4, true),
  ('74a1e4ac-5729-4676-a7aa-54d113a233df', 'inovacao', 'Mundo Ideal', 'Pensar grande antes de restringir por limitações.', 'Papel, canetas, espaço para apresentação.', 'Grupos imaginam a solução perfeita sem restrições de recursos ou tecnologia. Depois, trazem elementos para a realidade.', 'Sonhe grande na fase ideal e seja criativo ao adaptar para a realidade mantendo a essência.', 5, true),
  ('6041242f-fc9c-47b0-b2d6-0b5dfdb3dad6', 'inovacao', 'Hackathon Express', 'Desenvolver soluções sob pressão de tempo.', 'Materiais variados, computadores se necessário.', 'Equipes têm tempo limitado para desenvolver um protótipo ou solução funcional para um desafio específico.', 'Foque no MVP (produto mínimo viável), delegue tarefas e mantenha a equipe energizada.', 6, true),
  ('1a346983-1a6a-4e1a-8874-57ca814f3e96', 'inovacao', 'Biomimética', 'Buscar inspiração na natureza para inovação.', 'Imagens ou informações sobre soluções naturais.', 'O grupo estuda como a natureza resolve problemas semelhantes ao desafio proposto e adapta essas soluções.', 'Pesquise exemplos reais de biomimética e faça conexões criativas com o desafio do grupo.', 7, true),
  ('3f222ea8-7104-4e7c-8476-55531fb6fc65', 'inovacao', 'Future Thinking', 'Antecipar tendências e preparar-se para o futuro.', 'Artigos sobre tendências, papel e caneta.', 'Grupos analisam tendências atuais e projetam como elas afetarão um setor específico em 5, 10, 20 anos.', 'Baseie projeções em dados reais e conecte múltiplas tendências para cenários mais completos.', 8, true),
  ('2d7d4a7a-0b3d-4794-a5ae-dc48c1e1c7f1', 'inovacao', 'Laboratório de Protótipos', 'Materializar ideias rapidamente.', 'Materiais diversos (papel, cartolina, fita, etc.).', 'Após geração de ideias, grupos têm tempo limitado para criar protótipos físicos de suas soluções.', 'Seja hands-on, teste diferentes materiais e crie protótipos que comuniquem claramente a ideia.', 9, true),
  ('5da0236a-07ed-4c28-8a2c-431734e0a0b2', 'inovacao', 'Pitch Tank', 'Apresentar e defender ideias inovadoras.', 'Espaço para apresentações, cronômetro.', 'Como um Shark Tank, participantes apresentam suas ideias para um painel que faz perguntas e dá feedback.', 'Prepare um pitch envolvente, antecipe perguntas e demonstre paixão pela sua ideia sem ser defensivo.', 10, true),
  ('e32a4a4f-b561-46c5-a172-223fa29a87d3', 'autoconhecimento', 'Janela de Johari', 'Desenvolver autoconhecimento através de feedback.', 'Folha com matriz Johari, canetas.', 'Cada pessoa preenche sua matriz e recebe feedback dos colegas sobre aspectos conhecidos e desconhecidos.', 'Esteja aberto ao feedback, agradeça contribuições e reflita genuinamente sobre pontos cegos revelados.', 1, true),
  ('54b3f45e-9cde-45ef-acb4-a00caef376f6', 'autoconhecimento', 'Valores em Ação', 'Identificar e priorizar valores pessoais.', 'Lista de valores, papel e caneta.', 'Participantes escolhem seus 5 valores mais importantes de uma lista, justificam e compartilham com o grupo.', 'Relacione seus valores com a profissão de comissário(a) e dê exemplos concretos de como você os pratica.', 2, true),
  ('5ac6dbf9-4e80-4c42-a6ab-406be06af61a', 'autoconhecimento', 'Feedback 360', 'Receber e dar feedback construtivo.', 'Formulários de feedback, espaço privado.', 'Cada participante recebe feedback anônimo dos colegas e reflete sobre padrões identificados.', 'Aceite feedback com gratidão, faça perguntas esclarecedoras e demonstre disposição para crescer.', 3, true),
  ('b6b22e7e-aea3-42f2-8488-df5666b95465', 'autoconhecimento', 'Linha da Vida', 'Refletir sobre experiências formativas e aprendizados.', 'Papel grande, canetas coloridas.', 'Cada pessoa desenha uma linha representando sua vida, marcando altos, baixos e momentos decisivos.', 'Compartilhe como superou desafios e o que aprendeu. Relacione experiências com sua motivação para a carreira.', 4, true),
  ('105a5299-75c7-48cd-b940-1d1b78be917e', 'autoconhecimento', 'Espelho de Qualidades', 'Reconhecer qualidades em si e nos outros.', 'Post-its, canetas, espelho ou foto pessoal.', 'Participantes escrevem qualidades uns dos outros em post-its, que são colados nas costas de cada pessoa.', 'Seja generoso ao identificar qualidades nos outros e aceite elogios com graça.', 5, true),
  ('f42dfc78-2ac9-4d4b-8d99-d62dda4a420c', 'autoconhecimento', 'Roda da Vida', 'Avaliar equilíbrio entre diferentes áreas da vida.', 'Diagrama de roda da vida impresso, canetas.', 'Cada pessoa avalia de 0 a 10 diversas áreas (carreira, saúde, relacionamentos, etc.) e identifica desequilíbrios.', 'Seja honesto na avaliação e proponha ações concretas para áreas deficientes.', 6, true),
  ('d93a7b10-097c-475a-9eda-e6526c20d120', 'autoconhecimento', 'Carta para o Futuro', 'Definir metas e comprometimentos pessoais.', 'Papel, envelopes, canetas.', 'Cada pessoa escreve uma carta para si mesmo no futuro, definindo metas e compromissos.', 'Seja específico nas metas, inclua prazos e demonstre autoconhecimento ao identificar o que precisa mudar.', 7, true),
  ('f342cbec-cbf2-40ff-a8c2-32aff728201a', 'autoconhecimento', 'Árvore de Competências', 'Mapear habilidades e áreas de desenvolvimento.', 'Desenho de árvore, post-its coloridos.', 'Raízes são valores, tronco são competências atuais, galhos são habilidades em desenvolvimento, frutos são conquistas.', 'Seja detalhista e inclua competências relevantes para aviação. Identifique gaps com maturidade.', 8, true),
  ('841bbcc0-0dc3-4f8e-a3e9-d6e3396878af', 'autoconhecimento', 'Meu Personagem Ideal', 'Definir a pessoa que você quer se tornar.', 'Papel, canetas, revistas para colagem.', 'Participantes criam um personagem que representa quem eles querem ser em 5 anos.', 'Seja ambicioso mas realista. Inclua aspectos profissionais, pessoais e valores do personagem.', 9, true),
  ('552e365b-1f0c-41a1-b9d7-177bfe808bdc', 'autoconhecimento', 'Inventário de Emoções', 'Desenvolver inteligência emocional.', 'Lista de emoções, papel e caneta.', 'Participantes identificam situações que geram diferentes emoções e como normalmente reagem.', 'Demonstre autocrítica construtiva e compartilhe estratégias de gestão emocional que funcionam para você.', 10, true),
  ('46226cde-3e43-4981-8149-1dc827577967', 'lideranca', 'Líder por um Dia', 'Experimentar diferentes estilos de liderança.', 'Tarefas para grupos, cronômetro.', 'Cada pessoa lidera o grupo por um período, aplicando um estilo de liderança diferente.', 'Adapte seu estilo à situação, dê instruções claras e mantenha a equipe motivada.', 1, true),
  ('7b3086ba-ee60-46e2-8821-83713c888d3e', 'lideranca', 'Delegação Efetiva', 'Praticar atribuição de tarefas baseada em habilidades.', 'Lista de tarefas complexas, perfis de equipe fictícios.', 'O líder deve distribuir tarefas considerando habilidades e desenvolvimento de cada membro.', 'Justifique suas escolhas de delegação e demonstre conhecimento das forças de cada pessoa.', 2, true),
  ('53fe10d0-6110-4af5-af54-0f9ad5836a1b', 'lideranca', 'Gestão de Conflitos', 'Mediar conflitos de forma construtiva.', 'Cenários de conflito escritos em cartões.', 'Participantes recebem cenários de conflito e devem propor soluções que atendam todas as partes.', 'Ouça todas as partes, busque interesses comuns e proponha soluções ganha-ganha.', 3, true),
  ('6bf7b167-d601-466c-816b-4b15bd4b8b7e', 'lideranca', 'Coaching Express', 'Desenvolver habilidades de coaching.', 'Perguntas de coaching preparadas.', 'Em duplas, um atua como coach ajudando o outro a encontrar soluções através de perguntas poderosas.', 'Faça perguntas abertas que estimulem reflexão. Não dê respostas, ajude o outro a encontrá-las.', 4, true),
  ('df541de9-c25f-4fe3-8a08-c32c417fda71', 'lideranca', 'Feedback Sandwich', 'Praticar dar feedback construtivo.', 'Situações para feedback escritas em cartões.', 'Participantes praticam dar feedback usando a técnica do sanduíche: positivo, melhoria, positivo.', 'Seja específico, focado em comportamentos e genuíno nos elogios.', 5, true),
  ('2a841b57-d713-4d7d-959c-e7e3a133637b', 'lideranca', 'Reunião de Alinhamento', 'Praticar condução de reuniões eficientes.', 'Pauta de reunião, cronômetro.', 'Um participante conduz uma reunião com tempo limitado, mantendo foco e garantindo participação de todos.', 'Gerencie o tempo, dê voz a todos e conclua com ações claras e responsáveis designados.', 6, true),
  ('452fd15c-d6a5-4414-9a21-e251213ce2ae', 'lideranca', 'Motivação de Equipe', 'Inspirar e motivar colegas em situações difíceis.', 'Cenário de crise ou desmotivação.', 'O líder deve motivar uma equipe desanimada diante de um cenário adverso.', 'Use empatia, reconheça dificuldades e apresente uma visão positiva sem minimizar problemas.', 7, true),
  ('efdd2581-a973-4be2-a275-9dbe3ceee77d', 'lideranca', 'Tomada de Decisão sob Pressão', 'Decidir rapidamente com informações limitadas.', 'Cenários de emergência com opções de decisão.', 'O líder recebe um cenário de emergência e deve tomar decisões rápidas, explicando seu raciocínio.', 'Mantenha a calma, priorize segurança e comunique decisões com clareza e confiança.', 8, true),
  ('4ba6c9a3-2746-443f-9f7f-1f06a7ddd076', 'lideranca', 'Mentoria Reversa', 'Aprender com diferentes perspectivas.', 'Temas para discussão entre gerações/experiências.', 'Pessoas menos experientes mentoram mais experientes em temas que dominam melhor.', 'Valorize conhecimentos diversos, seja humilde para aprender e generoso para ensinar.', 9, true),
  ('d6af1176-77a8-488b-b240-cb5fa96435ea', 'lideranca', 'Liderança Servidora', 'Praticar liderança focada em servir a equipe.', 'Tarefas que exigem suporte do líder.', 'O líder deve apoiar a equipe a realizar uma tarefa, removendo obstáculos e fornecendo recursos.', 'Foque em como ajudar os outros a terem sucesso. Demonstre humildade e disposição para servir.', 10, true),
  ('15c0601f-2c32-4719-a181-84c4ecc9f933', 'energizadores', 'Ginástica Laboral Criativa', 'Ativar o corpo e a mente.', 'Espaço para movimentação.', 'Participantes se revezam liderando exercícios criativos de alongamento e movimentação.', 'Seja criativo nos movimentos e encoraje participação animada de todos.', 1, true),
  ('e14b69ce-d740-4291-accd-828f0eb55b19', 'energizadores', 'Dança das Cadeiras Cooperativa', 'Energizar através de movimento e música.', 'Cadeiras, música animada.', 'Versão cooperativa: ao parar a música, todos devem encontrar um lugar, mesmo que seja no colo de alguém.', 'Ajude colegas a encontrar espaço, celebre soluções criativas e mantenha energia alta.', 2, true),
  ('bd520a9f-6858-4447-9c97-ea5ef6dcd320', 'energizadores', 'Contagem Coletiva', 'Desenvolver atenção e sintonia do grupo.', 'Nenhum material necessário.', 'Grupo deve contar até 20 sem que duas pessoas falem ao mesmo tempo. Se isso acontecer, recomeça.', 'Esteja atento ao grupo, espere seu momento e celebre quando conseguirem.', 3, true),
  ('ad36852d-9a7b-4dbd-9014-aa79ba3864c6', 'energizadores', 'Grito de Guerra', 'Criar identidade e energia de grupo.', 'Nenhum material necessário.', 'Equipes criam um grito de guerra criativo que representa seus valores e o apresentam.', 'Seja criativo, inclua elementos relevantes para aviação e lidere com entusiasmo.', 4, true),
  ('28164db7-c49a-4ed1-a4d9-0206911038ce', 'energizadores', 'Estátua', 'Ativar reflexos e atenção.', 'Música animada, espaço para dançar.', 'Participantes dançam e devem congelar quando a música para, mantendo a pose.', 'Seja expressivo ao dançar e criativo nas poses. Celebre as melhores estátuas.', 5, true),
  ('f52c28ef-ba6d-459c-9320-7ba28c2d3057', 'energizadores', 'Zip Zap Zop', 'Desenvolver reflexos e atenção.', 'Nenhum material necessário.', 'Em círculo, passam energia dizendo Zip, Zap ou Zop com gestos específicos. Errou, sai.', 'Mantenha energia alta, ajude quem errou a não ficar constrangido e celebre jogadas criativas.', 6, true),
  ('e1b6d0db-4466-470e-a57b-e09ea9a3c182', 'energizadores', 'Massagem em Círculo', 'Relaxar e criar conexão através do toque.', 'Nenhum material necessário.', 'Em círculo, cada pessoa faz massagem nos ombros de quem está à frente. Depois, viram e retribuem.', 'Seja respeitoso, pergunte a pressão adequada e demonstre cuidado com o colega.', 7, true),
  ('bb85747e-3697-4f80-908b-bf3571bee2e2', 'energizadores', 'Karaokê Corporativo', 'Energizar através de música e diversão.', 'Sistema de som, letras de músicas.', 'Equipes ou indivíduos cantam músicas adaptadas com temas do processo seletivo ou empresa.', 'Participe com entusiasmo, mesmo que não cante bem. Adapte letras de forma criativa.', 8, true),
  ('8f143429-6809-4bb0-963b-21933565eb55', 'energizadores', 'Desafio do Minuto', 'Criar energia através de competições rápidas.', 'Materiais variados para mini-desafios.', 'Séries de desafios de 1 minuto: quem faz mais polichinelos, quem empilha mais copos, etc.', 'Dê seu melhor em cada desafio e torça pelos colegas. Celebre vitórias sem arrogância.', 9, true),
  ('a60b0a64-2ad5-46d5-9dff-a7ee8c0722d2', 'energizadores', 'Roda de Energia', 'Aumentar energia do grupo rapidamente.', 'Espaço amplo.', 'Em círculo, o grupo faz movimentos cada vez mais intensos, terminando com um grito coletivo.', 'Participe com toda energia, encoraje colegas mais tímidos e celebre o momento final.', 10, true),
  ('0a490bcf-8e21-43a4-9601-7962c3624c30', 'encerramento', 'Rede de Apoio', 'Visualizar e fortalecer conexões do grupo.', 'Novelo de lã ou barbante.', 'Em círculo, cada pessoa joga o novelo para alguém agradecendo ou elogiando, criando uma rede visual.', 'Seja genuíno nos elogios e mencione contribuições específicas de cada pessoa.', 1, true),
  ('710eb0c9-cad5-49bf-84bf-50771f8485ac', 'encerramento', 'Árvore de Agradecimentos', 'Cultivar gratidão e reconhecimento.', 'Desenho de árvore grande, post-its em forma de folha.', 'Participantes escrevem agradecimentos aos colegas e colam na árvore, que fica exposta.', 'Agradeça atitudes específicas e inclua todos que contribuíram de alguma forma.', 2, true),
  ('cd5605fd-7dd7-4d83-a4e3-eeb32911ac76', 'encerramento', 'Pacto de Grupo', 'Estabelecer compromissos coletivos.', 'Papel grande, canetas, espaço para assinaturas.', 'O grupo define valores e comportamentos que todos se comprometem a seguir, assinando o pacto.', 'Proponha compromissos relevantes e seja o primeiro a demonstrar adesão aos valores definidos.', 3, true),
  ('2c77fad4-23f6-4b53-b844-c65e4128c0c5', 'encerramento', 'Mural de Memórias', 'Criar registro visual das experiências compartilhadas.', 'Papel grande, fotos, canetas, materiais de colagem.', 'Grupo cria colaborativamente um mural com fotos, desenhos e mensagens sobre a experiência juntos.', 'Contribua ativamente, inclua momentos marcantes e ajude a organizar o mural de forma bonita.', 4, true),
  ('891333ac-1779-42ea-88d9-f8ce12fc62c7', 'encerramento', 'Cadeira Quente Positiva', 'Receber reconhecimento dos colegas.', 'Uma cadeira especial no centro do círculo.', 'Cada pessoa senta na cadeira quente e recebe elogios e reconhecimentos de todos os colegas.', 'Aceite elogios com gratidão, sem minimizar. Ao elogiar outros, seja específico e sincero.', 5, true),
  ('4d1d6f75-dc7c-49a0-b25e-ad21fd62877e', 'encerramento', 'Presente Simbólico', 'Demonstrar cuidado através de gestos simbólicos.', 'Papel, canetas, materiais para criar presentes.', 'Cada pessoa cria ou escolhe um presente simbólico para outra pessoa do grupo, explicando o significado.', 'Escolha algo significativo que demonstre que você realmente conheceu e observou a pessoa.', 6, true),
  ('5954a7e7-0cc9-42b9-b49e-8d7518fb0187', 'encerramento', 'Cápsula do Tempo', 'Criar conexão entre presente e futuro.', 'Caixa, papéis, objetos simbólicos.', 'Grupo cria uma cápsula do tempo com mensagens e objetos para ser aberta em data futura combinada.', 'Contribua com mensagens inspiradoras e objetos que representem este momento especial.', 7, true),
  ('93592e7b-531e-4785-aeaa-9b650850246a', 'encerramento', 'Ritual de Despedida', 'Encerrar ciclos de forma significativa.', 'Vela, música suave, espaço acolhedor.', 'Em círculo, cada pessoa compartilha aprendizados e agradecimentos finais ao grupo.', 'Seja vulnerável e autêntico. Compartilhe impacto real que o grupo teve em você.', 8, true),
  ('ef4c92fb-76e6-4005-b5ba-2f1701650ed2', 'encerramento', 'Rede de Contatos Viva', 'Fortalecer networking e conexões futuras.', 'Cartões de visita ou papéis, canetas.', 'Participantes trocam informações de contato de forma criativa, combinando formas de manter contato.', 'Demonstre interesse genuíno em manter contato e proponha formas concretas de se conectar.', 9, true),
  ('b136e2e5-7e50-4da7-ac72-8a50cb68a756', 'encerramento', 'Compromisso Coletivo', 'Definir ações conjuntas para após o evento.', 'Papel, canetas, calendário.', 'Grupo define ações concretas que farão juntos após o evento (reencontro, grupo de estudos, etc.).', 'Proponha iniciativas viáveis e seja o primeiro a se comprometer com datas e responsabilidades.', 10, true),
  ('156d698d-e79d-4210-b039-25a060d83b18', 'planejamento', 'Canvas de Projeto', 'Estruturar ideias de forma visual.', 'Canvas impresso grande, post-its, canetas.', 'Grupos preenchem um canvas de modelo de negócio ou projeto, definindo elementos essenciais.', 'Contribua em todas as áreas do canvas e ajude a manter coerência entre os elementos.', 1, true),
  ('d78739d7-13e3-4668-bcc9-5be809c1061e', 'planejamento', 'Retrospectiva Ágil', 'Refletir e melhorar continuamente.', 'Post-its coloridos, quadro ou parede.', 'Grupo reflete sobre o que funcionou bem, o que pode melhorar e ações para a próxima etapa.', 'Seja construtivo nas críticas, reconheça acertos e proponha ações específicas de melhoria.', 2, true),
  ('fa2a9767-01dd-4fe8-bf0a-ec9ae2bf43c7', 'planejamento', 'Planejamento por Sprints', 'Organizar trabalho em ciclos curtos.', 'Quadro kanban, post-its, canetas.', 'Grupo define tarefas para um período curto (sprint), priorizando e distribuindo responsabilidades.', 'Ajude a estimar tempo realista, identifique dependências e ofereça ajuda a colegas sobrecarregados.', 3, true),
  ('1c21dd98-7418-4cb6-bcbc-4868f1e785cc', 'planejamento', 'Check-in Check-out', 'Iniciar e encerrar atividades com intencionalidade.', 'Nenhum material necessário.', 'No início, cada pessoa compartilha como está chegando. No final, o que está levando.', 'Seja breve mas significativo. Demonstre presença e abertura para o momento.', 4, true),
  ('7e0e4cb2-d917-4037-a998-17fd03f5e1e0', 'planejamento', 'Roda de Feedback', 'Dar e receber feedback estruturado.', 'Perguntas de feedback preparadas.', 'Em rodízio, cada pessoa recebe feedback do grupo seguindo uma estrutura: continuar, parar, começar.', 'Dê feedback específico e acionável. Receba com abertura e agradeça contribuições.', 5, true),
  ('fbd18a8c-9eac-4485-9c92-d328d9a70c67', 'planejamento', 'Metas SMART', 'Definir objetivos claros e mensuráveis.', 'Folhas com template SMART, canetas.', 'Participantes definem metas seguindo critérios SMART: Específica, Mensurável, Atingível, Relevante, Temporal.', 'Seja ambicioso mas realista. Defina indicadores claros de sucesso e prazos concretos.', 6, true),
  ('8f6f021d-5499-4ae1-adf0-53f67b7fc327', 'planejamento', 'Daily Standup', 'Praticar reuniões rápidas de alinhamento.', 'Cronômetro, espaço em pé.', 'Em pé, cada pessoa tem 1 minuto para dizer: o que fez ontem, o que fará hoje, impedimentos.', 'Seja conciso, foque no essencial e ofereça ajuda quando ouvir impedimentos de colegas.', 7, true),
  ('c1aa5e32-dcf9-466b-b5c7-74d7e3244f39', 'planejamento', 'Avaliação 1-10', 'Coletar feedback rápido e quantificável.', 'Papel para votação ou mãos para mostrar números.', 'Após cada atividade, participantes dão nota de 1 a 10 e justificam brevemente.', 'Seja honesto na avaliação e construtivo na justificativa. Proponha melhorias específicas.', 8, true),
  ('5d3ab56b-a69e-498f-b2e6-d1af4ef8c938', 'planejamento', 'Plano de Ação 5W2H', 'Estruturar ações de forma completa.', 'Template 5W2H impresso, canetas.', 'Para cada ação definida, grupo preenche: O quê, Por quê, Onde, Quando, Quem, Como, Quanto custa.', 'Ajude a garantir que todos os campos estejam preenchidos de forma clara e realista.', 9, true),
  ('417557a6-c9dd-4fd3-89a8-097648123da7', 'planejamento', 'Termômetro de Satisfação', 'Medir clima e satisfação do grupo.', 'Termômetro desenhado grande, adesivos.', 'Participantes marcam no termômetro seu nível de satisfação e comentam o que influencia.', 'Seja honesto sobre seu nível, explique fatores e proponha ações para melhorar o clima.', 10, true)
) as v(origem, slug, titulo, objetivo, materiais, como, destaque, ordem, ativo)
join dinamicas_categorias c on c.slug = v.slug
on conflict (origem_id) do update set categoria_id = excluded.categoria_id, titulo = excluded.titulo, objetivo = excluded.objetivo,
  materiais = excluded.materiais, como_realizada = excluded.como_realizada, como_se_destacar = excluded.como_se_destacar,
  ordem = excluded.ordem, ativo = excluded.ativo;

-- a biblioteca aparece no módulo de Dinâmicas de Grupo
update modulos set recurso = 'dinamicas' where curso = 'head-hunter' and recurso is null and titulo ilike '%din_mica%';

commit;

select c.titulo as categoria, count(d.id) as dinamicas from dinamicas_categorias c left join dinamicas d on d.categoria_id = c.id group by c.titulo, c.ordem order by c.ordem;
